#![allow(dead_code)]
mod document { #[derive(Clone, Copy)] pub enum DocumentKind { Tex, Typst, Other } }
#[path="/Users/calvinkhor/Documents/GitHub/mytypst/src/editor_math_guides.rs"] mod editor_math_guides;
mod writing {
    #[path="/Users/calvinkhor/Documents/GitHub/mytypst/src/writing/prose_rules.rs"] pub(crate) mod prose_rules;
    #[path="/private/tmp/mytypst-tex-prose-baseline.rs"] mod baseline;
    #[path="/Users/calvinkhor/Documents/GitHub/mytypst/src/writing/tex_prose.rs"] mod improved;
    pub fn parse(source: &[char], improved: bool) -> usize {
        use harper_core::parsers::Parser;
        if improved { improved::TexProse.parse(source).len() }
        else { baseline::TexProse.parse(source).len() }
    }
}
fn main() {
    let paragraph = r"\section{Energy estimates}
We establish \emph{the energy estimate} for the solution and obtain a uniform bound.
\begin{align*}
  \|u(t)\|^2 &\leq C \|u_0\|^2, \\
  \text{where the constant is independent of time.}
\end{align*}
The estimate follows by \textbf{integration by parts} and the argument is complete.
The \href{https://example.invalid/paper}{supporting calculation} gives the result.
\label{sec:energy-estimate}

";
    let source = format!("\\documentclass{{article}}\n\\usepackage{{amsmath,hyperref}}\n\\begin{{document}}\n{}\\end{{document}}\n", paragraph.repeat(300));
    let chars: Vec<_> = source.chars().collect();
    for _ in 0..10 { std::hint::black_box(writing::parse(&chars, false)); std::hint::black_box(writing::parse(&chars, true)); }
    let mut old = Vec::new(); let mut new = Vec::new();
    let mut counts = [0;2];
    for round in 0..50 {
        for improved in if round%2 == 0 { [false,true] } else { [true,false] } {
            let start = std::time::Instant::now();
            let count = std::hint::black_box(writing::parse(std::hint::black_box(&chars), improved));
            let micros = start.elapsed().as_secs_f64()*1e6;
            counts[usize::from(improved)] = count;
            if improved { new.push(micros); } else { old.push(micros); }
        }
    }
    old.sort_by(f64::total_cmp); new.sort_by(f64::total_cmp);
    println!("{{\"profile\":\"rustc -C opt-level=3, same dependency rlibs\",\"math_scanner\":\"actual editor_math_guides.rs\",\"fixture\":\"300 repeated realistic TeX energy-estimate sections\",\"bytes\":{},\"scalars\":{},\"warmups\":10,\"samples\":50,\"baseline_p50_us\":{},\"improved_p50_us\":{},\"baseline_p95_us\":{},\"improved_p95_us\":{},\"token_counts\":{:?}}}", source.len(), chars.len(), old[25],new[25],old[47],new[47],counts);
}
